<section class="panel form-panel" id="analytics-board-<?=$metric?>" data-analytics-board data-endpoint="/?page=analytics_data">
<h2><?=e($heading)?></h2><p><?=e($description)?></p><form method="get" class="filter-form" id="analytics-filters-<?=$metric?>"><input type="hidden" name="page" value="analytics"><input type="hidden" name="metric" value="<?=e($metric)?>"><label>Vigencia<select name="year"><?php foreach($data['years'] as $y): ?><option value="<?=$y?>" <?=$data['year']===(string)$y?'selected':''?>><?=$y?></option><?php endforeach; ?><option value="all" <?=$data['year']==='all'?'selected':''?>>Todas las vigencias</option></select></label><label>Dependencia<select name="department"><option value="all">Todas las dependencias</option><?php foreach($data['department_options'] as $d): ?><option value="<?=(int)$d['id']?>" <?=$data['department']===(string)$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach; ?></select></label><button class="button secondary">Consultar</button><a class="button secondary" id="analytics-export-<?=$metric?>" href="/?page=analytics_export&amp;metric=<?=e($metric)?>&amp;year=<?=e($data['year'])?>&amp;department=<?=e($data['department'])?>">Exportar para Power BI</a></form>
<p id="analytics-status-<?=$metric?>" role="status">Actualizado: <?=e($data['generated_at'])?> · Bogotá. Actualización automática cada 30 segundos.</p>
<div class="stats-grid analytics-cards"><?php foreach(['total'=>'Total de solicitudes','permiso'=>'Permisos','compensatorio'=>'Compensatorios','licencia'=>'Licencias'] as $key=>$label): ?><article class="panel stat-card"><span><?=e($label)?></span><strong data-count="<?=$key?>"><?=$data['counts'][$key]?></strong></article><?php endforeach; ?></div>
<h2>Distribución por dependencias</h2><div class="table-wrap"><table><thead><tr><th>Dependencia</th><th>Permisos</th><th>Compensatorios</th><th>Licencias</th><th>Total</th></tr></thead><tbody id="analytics-departments-<?=$metric?>"><?php foreach($data['departments'] as $d): ?><tr><td><?=e($d['name'])?></td><td><?=$d['permiso']?></td><td><?=$d['compensatorio']?></td><td><?=$d['licencia']?></td><td><?=$d['total']?></td></tr><?php endforeach; ?></tbody></table></div>
<h2>Comparación histórica por vigencia</h2><p class="fine">La comparación muestra todas las vigencias con solicitudes de la dependencia seleccionada.</p><div id="analytics-trend-<?=$metric?>" class="analytics-trend"><?php foreach($data['trend'] as $row): ?><p><?=$row['year']?> · Permisos <?=$row['permiso']?> · Compensatorios <?=$row['compensatorio']?> · Licencias <?=$row['licencia']?></p><?php endforeach; if(!$data['trend']): ?><p>Sin solicitudes registradas para esta selección.</p><?php endif; ?></div>
<p class="fine">Cada solicitud cuenta una vez dentro de la selección. Una solicitud puede aparecer en varias vigencias si tiene tiempo en ellas; la suma de los años puede superar el total único. La dependencia corresponde al trámite, no a la asignación actual del funcionario. Licencias incluye remuneradas y no remuneradas.</p>
<script type="application/json" class="analytics-initial"><?=json_encode($data,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?></script></section>
